# ---------------- writer + self-check ----------------
assert len(P) == 60, len(P)
for cid, v in P.items():
    rec = {"case_id": cid, "prediction_text": v["prediction_text"], "basis": v["basis"],
           "confidence": v["conf"], "trigger": v["trig"]}
    with open(os.path.join(OUT, cid + ".json"), "w", encoding="utf-8") as f:
        json.dump(rec, f, ensure_ascii=False, indent=1)
# self-verify: re-read each written file
bad = []
cm = ru = di = 0
for cid in P:
    r = json.load(open(os.path.join(OUT, cid + ".json"), encoding="utf-8"))
    if r["case_id"] != cid or set(r.keys()) != {"case_id","prediction_text","basis","confidence","trigger"}:
        bad.append(cid)
    t = r["trigger"]
    cm += bool(t["changed_main"]); ru += bool(t["reserve_used"]); di += bool(t["disputed"])
print("written:", len(P), "bad:", bad)
print("trigger counts: changed_main=%d reserve_used=%d disputed=%d" % (cm, ru, di))
